  id: 'calendar',
  name: 'Calendar',
  description: 'Displays events',
  defaultVariant: 'month',
  variants: {
    month: {
      props: {},
      minSize: { width: 4, height: 4 },
      actions: [
        {
          name: 'showWeek',
          description: 'Switch to week view',
          transitionsTo: 'week',
        },
      ],
    },
    week: {
      props: {},
      minSize: { width: 6, height: 4 },
      actions: [],
    },
  },
};

