import { act, cleanup, fireEvent, render, screen } from '@testing-library/react';
import '@testing-library/jest-dom/vitest';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { maelstrom } from './App';
import { SearchPanel, searchPanelVessel } from './SearchPanel';
import { searchTickets, type SearchResult } from './search';

vi.mock('./search', () => ({ searchTickets: vi.fn() }));

const searchTicketsMock = vi.mocked(searchTickets);

function submitSearch(query: string) {
  render(<SearchPanel />);
  fireEvent.change(screen.getByLabelText('Search tickets'), { target: { value: query } });
  fireEvent.submit(screen.getByRole('button', { name: 'Search' }).closest('form')!);
}

afterEach(cleanup);

beforeEach(() => {
  vi.resetAllMocks();
});

describe('SearchPanel', () => {
  it('registers one developer-authored, single-variant Vessel with no Actions', () => {
    expect(maelstrom.vessels).toHaveLength(1);
    expect(maelstrom.vessels[0].vessel).toBe(searchPanelVessel);
    expect(maelstrom.vessels[0].component).toBe(SearchPanel);
    expect(searchPanelVessel.defaultVariant).toBe('search');
    expect(Object.keys(searchPanelVessel.variants)).toEqual(['search']);
    expect(searchPanelVessel.variants.search.actions).toEqual([]);
  });

  it('keeps empty submission disabled and calls the application-owned boundary with the query', async () => {
    searchTicketsMock.mockResolvedValue([{ id: 'T-104', subject: 'Billing' }]);
    render(<SearchPanel />);

    const button = screen.getByRole('button', { name: 'Search' });
    expect(button).toBeDisabled();
    fireEvent.change(screen.getByLabelText('Search tickets'), { target: { value: 'billing' } });
    expect(button).toBeEnabled();
    fireEvent.click(button);

    expect(searchTicketsMock).toHaveBeenCalledExactlyOnceWith('billing');
    expect(await screen.findByRole('status')).toHaveTextContent('1 results');
  });

  it('shows the pending state until the existing search handler resolves', async () => {
    let resolveSearch!: (results: SearchResult[]) => void;
    searchTicketsMock.mockImplementation(() => new Promise((resolve) => { resolveSearch = resolve; }));
    submitSearch('billing');

    const button = screen.getByRole('button', { name: 'Searching…' });
    expect(button).toBeDisabled();
    expect(searchTicketsMock).toHaveBeenCalledExactlyOnceWith('billing');

    await act(async () => resolveSearch([{ id: 'T-104', subject: 'Billing' }]));
    expect(await screen.findByRole('status')).toHaveTextContent('1 results');
    expect(screen.getByRole('button', { name: 'Search' })).toBeEnabled();
  });

  it('preserves the existing error feedback when the search handler rejects', async () => {
    searchTicketsMock.mockRejectedValue(new Error('offline'));
    submitSearch('billing');

    expect(await screen.findByRole('alert')).toHaveTextContent('Search is temporarily unavailable.');
    expect(screen.getByRole('button', { name: 'Search' })).toBeEnabled();
    expect(searchTicketsMock).toHaveBeenCalledExactlyOnceWith('billing');
  });
});

